   303      uint32_t getULong(const byte* buf, ByteOrder byteOrder)
   304      {
   305          if (byteOrder == littleEndian) {
   306              return buf[3] << 24 | buf[2] << 16 | buf[1] << 8 | buf[0];
   307          }
   308          return buf[0] << 24 | buf[1] << 16 | buf[2] << 8 | buf[3];
   309      }
